import * as THREE from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();

  // ===== CONSTANTS =====
  const PLATE_WIDTH = 1.9;
  const PLATE_HEIGHT = 1.2;
  const PITCH = 1.5;
  const NUM_PLATES = 6;
  const COLUMN_OFFSET_X = 0.9;
  const LOOP_HEIGHT = 9.0;
  const BEVEL_WIDTH = 0.03;
  const ACCENT_WIDTH = 0.03;
  const DAMPING = 0.12;

  // ===== COLORS =====
  const COLORS = {
    background: new THREE.Color('#0b0b10'),
    surface: new THREE.Color('#14141a'),
    ink: new THREE.Color('#16161d'),
    paper: new THREE.Color('#e8ecf2'),
    accent: new THREE.Color('#ff2a38')
  };

  // ===== CAPTIONS =====
  const CAPTIONS = [
    'DIAL ROOM',
    'ESCAPEMENT BENCH',
    'CNC HALL',
    'FINISHING LAB',
    'ARCHIVE VAULT',
    'ASSEMBLY LINE ONE'
  ];

  // ===== STATE =====
  const state = {
    velocity: 0,
    offset: 0,
    focusIndex: 0,
    plates: [],
    accents: [],
    captions: [],
    tweens: {},
    updateFn: null
  };

  // ===== TEXTURE LOADING =====
  let imageTexture = null;
  if (config.metadata?.assets?.imageUrl) {
    imageTexture = ctx.textureLoader.load(config.metadata.assets.imageUrl);
    imageTexture.colorSpace = THREE.SRGBColorSpace;
  }

  // ===== MATERIALS =====
  const createPlateMaterial = () => new THREE.MeshPhysicalNodeMaterial({
    map: imageTexture,
    roughness: 0.6,
    metalness: 0.1,
    clearcoat: 0.1,
    colorSpace: THREE.SRGBColorSpace
  });

  const createBevelMaterial = () => new THREE.MeshPhysicalNodeMaterial({
    color: COLORS.ink,
    roughness: 0.5,
    metalness: 0.5,
    emissive: new THREE.Color(0x1a1a1a),
    emissiveIntensity: 0.3
  });

  const createAccentMaterial = () => new THREE.MeshPhysicalNodeMaterial({
    color: COLORS.accent,
    emissive: COLORS.accent,
    emissiveIntensity: 1.4,
    metalness: 0.3,
    roughness: 0.2
  });

  // ===== GEOMETRY HELPERS =====
  function createBevelFrame(bevelMat) {
    const parts = [];

    const top = new THREE.Mesh(
      new THREE.PlaneGeometry(PLATE_WIDTH + 2 * BEVEL_WIDTH, BEVEL_WIDTH),
      bevelMat.clone()
    );
    top.position.set(0, PLATE_HEIGHT / 2 + BEVEL_WIDTH / 2, 0.001);
    parts.push(top);

    const bot = new THREE.Mesh(
      new THREE.PlaneGeometry(PLATE_WIDTH + 2 * BEVEL_WIDTH, BEVEL_WIDTH),
      bevelMat.clone()
    );
    bot.position.set(0, -(PLATE_HEIGHT / 2 + BEVEL_WIDTH / 2), 0.001);
    parts.push(bot);

    const left = new THREE.Mesh(
      new THREE.PlaneGeometry(BEVEL_WIDTH, PLATE_HEIGHT),
      bevelMat.clone()
    );
    left.position.set(-(PLATE_WIDTH / 2 + BEVEL_WIDTH / 2), 0, 0.001);
    parts.push(left);

    const right = new THREE.Mesh(
      new THREE.PlaneGeometry(BEVEL_WIDTH, PLATE_HEIGHT),
      bevelMat.clone()
    );
    right.position.set(PLATE_WIDTH / 2 + BEVEL_WIDTH / 2, 0, 0.001);
    parts.push(right);

    return parts;
  }

  // ===== PLATE CREATION =====
  function createPlate(index) {
    const plateMesh = new THREE.Mesh(
      new THREE.PlaneGeometry(PLATE_WIDTH, PLATE_HEIGHT),
      createPlateMaterial()
    );
    plateMesh.position.set(COLUMN_OFFSET_X, -index * PITCH, 0);

    createBevelFrame(createBevelMaterial()).forEach(part => plateMesh.add(part));

    const accentMesh = new THREE.Mesh(
      new THREE.PlaneGeometry(ACCENT_WIDTH, PLATE_HEIGHT),
      createAccentMaterial()
    );
    accentMesh.position.set(-(PLATE_WIDTH / 2 + ACCENT_WIDTH / 2), 0, 0.002);
    accentMesh.visible = false;
    plateMesh.add(accentMesh);

    return { plate: plateMesh, accent: accentMesh };
  }

  // ===== CAPTION CREATION =====
  function createCaption(index, text) {
    const textMesh = ctx.fontAtlas.createTextMesh(text, {
      fontFamily: 'JetBrains Mono',
      fontSize: 18,
      fontWeight: 400,
      letterSpacing: 0.08,
      lineHeight: 1.4,
      color: COLORS.paper
    });
    textMesh.position.set(-1.6, -index * PITCH, 0.01);
    if (textMesh.material) {
      textMesh.material.transparent = true;
      textMesh.material.opacity = 0;
    }
    return textMesh;
  }

  // ===== INITIALIZATION =====
  function init() {
    for (let i = 0; i < NUM_PLATES; i++) {
      const { plate, accent } = createPlate(i);
      group.add(plate);
      state.plates.push(plate);
      state.accents.push(accent);

      const caption = createCaption(i, CAPTIONS[i]);
      group.add(caption);
      state.captions.push(caption);
    }

    const headline = ctx.fontAtlas.createTextMesh('Inside the atelier', {
      fontFamily: 'Lora',
      fontSize: 68,
      fontWeight: 600,
      letterSpacing: -0.005,
      lineHeight: 1.1,
      color: COLORS.paper
    });
    headline.position.set(-1.6, 1.9, 0);
    group.add(headline);

    if (ctx.primitives && typeof ctx.primitives['fly-through'] === 'function') {
      ctx.primitives['fly-through'](group, { depthUnits: 2.5 });
    }
  }

  // ===== UPDATE LOOP =====
  function updatePlates() {
    state.velocity *= (1 - DAMPING);
    state.offset += state.velocity;

    const wrapped = ((state.offset % LOOP_HEIGHT) + LOOP_HEIGHT) % LOOP_HEIGHT;

    let closestIdx = 0;
    let closestDist = Infinity;

    state.plates.forEach((plate, i) => {
      let y = -i * PITCH + wrapped;
      while (y > LOOP_HEIGHT / 2) y -= LOOP_HEIGHT;
      while (y <= -LOOP_HEIGHT / 2) y += LOOP_HEIGHT;

      plate.position.y = y;

      const dist = Math.abs(y);
      if (dist < closestDist) {
        closestDist = dist;
        closestIdx = i;
      }
    });

    if (closestIdx !== state.focusIndex) {
      updateFocus(closestIdx);
    }
  }

  // ===== FOCUS UPDATE =====
  function updateFocus(newIdx) {
    const oldIdx = state.focusIndex;

    if (state.tweens[oldIdx]) {
      state.tweens[oldIdx].forEach(t => t?.kill());
    }
    if (state.tweens[newIdx]) {
      state.tweens[newIdx].forEach(t => t?.kill());
    }

    state.tweens[oldIdx] = [
      gsap.to(state.plates[oldIdx].scale, {
        x: 1,
        y: 1,
        duration: 0.35,
        ease: 'cubic-bezier(0.215, 0.61, 0.355, 1)'
      }),
      gsap.to(state.captions[oldIdx].material, {
        opacity: 0,
        duration: 0.3,
        ease: 'power2.out'
      })
    ];
    state.accents[oldIdx].visible = false;

    state.tweens[newIdx] = [
      gsap.to(state.plates[newIdx].scale, {
        x: 1.06,
        y: 1.06,
        duration: 0.35,
        ease: 'cubic-bezier(0.215, 0.61, 0.355, 1)'
      }),
      gsap.to(state.captions[newIdx].material, {
        opacity: 1,
        duration: 0.3,
        ease: 'power2.out'
      })
    ];
    state.accents[newIdx].visible = true;

    state.focusIndex = newIdx;
  }

  // ===== EVENT HANDLERS =====
  function handleScroll(deltaY) {
    state.velocity += deltaY * 1.5;
  }

  // ===== SETUP TICKER =====
  const tickFn = gsap.ticker.add(() => updatePlates());
  state.updateFn = tickFn;

  init();

  group.userData.handlers = {
    scroll: handleScroll
  };

  group.userData.cleanup = () => {
    if (state.updateFn) {
      gsap.ticker.remove(state.updateFn);
    }

    Object.values(state.tweens).forEach(tweens => {
      if (Array.isArray(tweens)) {
        tweens.forEach(t => t?.kill());
      }
    });

    group.traverse((child) => {
      if (child.geometry) child.geometry.dispose();
      if (child.material && typeof child.material.dispose === 'function') {
        child.material.dispose();
      }
    });
  };

  return group;
}
